"""[10/20] Side-by-side videos + contact sheet of the HANDOFF arms (specwm/inject_handoff.py): for one scene + seed, decode T (14B 4-step alone),
1.3B alone, hand@3m1, hand@3m3, hand@6m2, once@6 and tile them 3 x 2 at 16 fps.  Border + chunk bar colour = WHO GENERATED THE SHOWN CHUNK:
orange = 1.3B, gray = 14B (T: all gray; alone: all orange; hand@k m: chunks k+1..k+m gray; once@6: chunks 0..6 are the 14B's latents -> gray).
Output: paper/1020/videos/handoff_<scene>_s<seed>.mp4 (+ handoff_ALL5_s<seed>.mp4), and for --sheet scene a 1-fps contact sheet
figs/sheet_handoff_<short>_s<seed>.png with a boundary strip (last / first frames around the two handoffs of hand@3m3).
usage: CUDA_VISIBLE_DEVICES=5 envrun python /home/hk28965/specwm/paper/1020/make_handoff_videos.py [SEED=1234] [scenes=comma list]"""
import os, sys, glob, subprocess, numpy as np, torch
from PIL import Image, ImageDraw, ImageFont
S = "/home/hk28965/specwm"; SEED = int(sys.argv[1]) if len(sys.argv) > 1 else 1234
R = S + "/lingbot-world-v2/specwm_out/inject/handoff"; RP = S + "/lingbot-world-v2/specwm_out/inject/1p3b_4step"; TD = S + "/lingbot-world-v2/specwm_out/paths2"
OUT = S + "/paper/1020/videos"; FIGS = S + "/paper/1020/figs"; os.makedirs(OUT, exist_ok=True); os.makedirs(FIGS, exist_ok=True)
FF = S + "/tools/ffmpeg-7.0.2-amd64-static/ffmpeg"; FPC = 3; FPS = 16
SCENES = sys.argv[2].split(",") if len(sys.argv) > 2 else ["sandcastle_wave_impact", "easy_stonehenge_sunset", "sand_filling_up_jar", "easy_lake", "pouring_water_into_cup"]
SHORT = {"sandcastle_wave_impact": "sandcastle", "easy_stonehenge_sunset": "stonehenge", "sand_filling_up_jar": "jar", "easy_lake": "lake", "pouring_water_into_cup": "pouring"}
# (arm, label, set of chunks generated by the 14B; None = all)
TILES = [("T", "T: 14B 4-step alone", None), ("alone", "1.3B 4-step alone", set()), ("hand@3m1", "hand@3m1: 14B takes over chunk 4 on the 1.3B context", {4}),
         ("hand@3m3", "hand@3m3: 14B takes over chunks 4-6", {4, 5, 6}), ("hand@6m2", "hand@6m2: 14B takes over chunks 7-8", {7, 8}), ("once@6", "once@6: 14B's own chunks 0-6 injected (reference)", set(range(7)))]
MODE = sys.argv[3] if len(sys.argv) > 3 else "hand"   # 'reject': tiles T / alone / hand@reject / hand@reject25 (if any) / hand@3m3 / once@6; the replaced chunks (run.json) are drawn gray
import json
if MODE == "reject": TILES = [TILES[0], TILES[1], ("hand@reject", "hand@reject: drift head (tau -3.25) -> 14B regenerates flagged chunks", "RUN"), ("hand@reject25", "hand@reject25: tau at the 25 % alone flag rate", "RUN"), TILES[3], TILES[5]]
sys.path.insert(0, S + "/lingbot-world-v2"); from wan.modules.vae2_1 import Wan2_1_VAE
vae = Wan2_1_VAE(vae_pth=S + "/lingbot-world-v2/lingbot-world-v2-14b-causal-fast/Wan2.1_VAE.pth", device="cuda:0")
@torch.no_grad()
def decode(lat):
    with torch.amp.autocast("cuda", dtype=torch.bfloat16): im = vae.decode([lat.float().cuda()])[0].float().clamp(-1, 1).cpu()
    return ((im + 1) / 2 * 255).permute(1, 2, 3, 0).numpy().astype("uint8")   # (F, H, W, 3)
try: FONT = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 15); FONT2 = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 13)
except Exception: FONT = FONT2 = ImageFont.load_default()
TW, TH, LH, BAR = 416, 240, 44, 10; COLS = 3; ORANGE = (255, 140, 0); GRAY = (170, 170, 170)
def chunk_of(f): return 0 if f < 9 else min(1 + (f - 9) // 12, 12)   # px frame -> chunk (latent frame 0 = 1 px frame, then 4 px frames per latent frame; chunk = 3 latent frames)
def tile(frame, label, who, f, nchunks):
    c = chunk_of(f); by14 = (who is None) or (c in who); col = GRAY if by14 else ORANGE
    im = Image.new("RGB", (TW, LH + TH + BAR + 4), (18, 18, 18))
    if frame is not None: im.paste(Image.fromarray(frame).resize((TW, TH), Image.BILINEAR), (0, LH))
    d = ImageDraw.Draw(im); d.text((6, 4), label, font=FONT, fill=(240, 240, 240))
    d.text((6, 24), "chunk %d / %d   generated by: %s" % (c, nchunks - 1, "14B" if by14 else "1.3B"), font=FONT2, fill=col)
    d.rectangle([0, LH, TW - 1, LH + TH - 1], outline=col, width=5); w = TW / nchunks
    for i in range(nchunks):
        d.rectangle([i * w + 1, LH + TH + 2, (i + 1) * w - 1, LH + TH + BAR], fill=GRAY if ((who is None) or (i in who)) else ORANGE)
        if i == c: d.rectangle([i * w + 1, LH + TH + 2, (i + 1) * w - 1, LH + TH + BAR], outline=(255, 255, 255), width=2)
    return np.asarray(im)
def write(frames_by_tile, labels, out, NCH):
    F = max(len(v) for v in frames_by_tile if v is not None); rows = (len(frames_by_tile) + COLS - 1) // COLS; th = LH + TH + BAR + 4
    p = subprocess.Popen([FF, "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", "%dx%d" % (TW * COLS, th * rows), "-r", str(FPS), "-i", "-",
                          "-c:v", "libx264", "-preset", "medium", "-crf", "20", "-pix_fmt", "yuv420p", "-movflags", "+faststart", out], stdin=subprocess.PIPE)
    for f in range(F):
        canvas = np.zeros((th * rows, TW * COLS, 3), np.uint8)
        for i, (frames, (label, who)) in enumerate(zip(frames_by_tile, labels)):
            r, c = divmod(i, COLS); canvas[r * th:(r + 1) * th, c * TW:(c + 1) * TW] = tile(frames[f] if frames is not None else None, label if frames is not None else label + " (missing)", who, f, NCH)
        p.stdin.write(canvas.tobytes())
    p.stdin.close(); p.wait()
def sheet(vids, task, seed, NCH):
    """1 fps contact sheet (frames 0, 16, ..., 160) per available row + boundary strip of hand@3m3: px frames 44 | 45 (chunk 3 -> 4) and 80 | 81 (chunk 6 -> 7)"""
    W = 200; rows = []
    for arm, lab, who in TILES:
        v = vids.get(arm)
        if v is None: continue
        idx = list(range(0, len(v), 16)); fr = [Image.fromarray(v[i]).resize((W, int(W * v.shape[1] / v.shape[2]))) for i in idx]; H = fr[0].size[1]
        row = Image.new("RGB", (W * len(fr), H + 30), "black"); d = ImageDraw.Draw(row); d.text((3, 1), "%s   %s s%d  (1 fps; chunk = 0.75 s; orange = 1.3B, gray = 14B)" % (lab, task, seed), font=FONT2, fill="white")
        for j, (i, f) in enumerate(zip(idx, fr)):
            c = chunk_of(i); col = GRAY if (who is None or c in who) else ORANGE; row.paste(f, (j * W, 30)); d.rectangle([j * W, 30, j * W + W - 1, 30 + H - 1], outline=col, width=4); d.text((j * W + 4, 16), "t=%ds c%d" % (i // 16, c), font=FONT2, fill=col)
        rows.append(row)
    v = vids.get("hand@3m3"); who = {4, 5, 6}
    if v is not None and MODE != "reject":
        idx = [40, 44, 45, 46, 52, 76, 80, 81, 82, 88]; fr = [Image.fromarray(v[i]).resize((W, int(W * v.shape[1] / v.shape[2]))) for i in idx]; H = fr[0].size[1]
        row = Image.new("RGB", (W * len(fr), H + 30), "black"); d = ImageDraw.Draw(row); d.text((3, 1), "hand@3m3 boundary strip: px frames around chunk 3->4 (14B takes over) and chunk 6->7 (1.3B resumes)", font=FONT2, fill="white")
        for j, (i, f) in enumerate(zip(idx, fr)):
            c = chunk_of(i); col = GRAY if c in who else ORANGE; row.paste(f, (j * W, 30)); d.rectangle([j * W, 30, j * W + W - 1, 30 + H - 1], outline=col, width=4); d.text((j * W + 4, 16), "px %d c%d" % (i, c), font=FONT2, fill=col)
        rows.append(row)
    sh = Image.new("RGB", (max(r.size[0] for r in rows), sum(r.size[1] for r in rows)), "black"); y = 0
    for r in rows: sh.paste(r, (0, y)); y += r.size[1]
    out = "%s/sheet_handoff_%s%s_s%d.png" % (FIGS, "reject_" if MODE == "reject" else "", SHORT[task], seed); sh.save(out); print("wrote", out, flush=True)
    np.savez_compressed("%s/.sheet_handoff_%s_s%d_frames.npz" % (OUT, SHORT[task], seed), **{k: v for k, v in vids.items()})
made = []
for sc in SCENES:
    paths = {"T": "%s/%s/tau2_s0/K0_uniform4P_fx_s%d/lat.pt" % (TD, sc, SEED), "alone": "%s/%s/alone_s%d/lat.pt" % (RP, sc, SEED), "once@6": "%s/%s/once@6_s%d/lat.pt" % (RP, sc, SEED)}
    for arm in ("hand@3m1", "hand@3m3", "hand@6m2", "hand@reject", "hand@reject25"): paths[arm] = "%s/%s/%s_s%d/lat.pt" % (R, sc, arm, SEED)
    have = {a: p for a, p in paths.items() if os.path.exists(p)}
    TILES = [(a_, l_, set(json.load(open(have[a_].replace("lat.pt", "run.json")))["replaced_chunks"]) if (w_ == "RUN" and a_ in have) else (set() if w_ == "RUN" else w_)) for a_, l_, w_ in TILES]
    if not any(a.startswith("hand") for a in have): print("skip", sc, "(no handoff arms yet)"); continue
    lat = {a: torch.load(p, map_location="cpu") for a, p in have.items()}; NCH = lat["T"].shape[1] // FPC
    vids = {a: decode(lat[a]) for a in lat}; out = "%s/handoff_%s_s%d.mp4" % (OUT, sc, SEED)
    if MODE == "reject": out = "%s/handoff_reject_%s_s%d.mp4" % (OUT, sc, SEED)
    write([vids.get(a) for a, _, _ in TILES], [(l, w) for _, l, w in TILES], out, NCH); made.append(out); print("wrote", out, [a for a in have], flush=True)
    if sc == "sandcastle_wave_impact": sheet(vids, sc, SEED, NCH)
if len(made) > 1:
    lst = OUT + "/.concat_handoff_s%d.txt" % SEED; open(lst, "w").write("".join("file '%s'\n" % m for m in made))
    subprocess.run([FF, "-v", "error", "-y", "-f", "concat", "-safe", "0", "-i", lst, "-c", "copy", "%s/handoff_%sALL5_s%d.mp4" % (OUT, "reject_" if MODE == "reject" else "", SEED)], check=True); print("wrote ALL5")
